module deserializer(  
    input clk,  
    input reset,  
    input serial_in,  
    output reg [31:0] parallel_out  
);  
    reg [4:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            parallel_out <= 32'b0;  
            count <= 5'b0;  
        end else if (count < 32) begin  
            parallel_out <= {parallel_out[30:0], serial_in};  
            count <= count + 1;  
        end  
    end  
endmodule

