module goertzel (
    input clk,
    input reset,
    input signed [15:0] sample,
    input signed [15:0] coeff,
    input [15:0] threshold,
    output reg detected
);
    reg signed [31:0] s_prev, s_prev2;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            s_prev <= 0;
            s_prev2 <= 0;
            detected <= 0;
        end else begin
            // Goertzel algorithm
            s_prev <= sample + (coeff * s_prev2);
            s_prev2 <= s_prev;

            // Detection logic
            if (s_prev * s_prev > threshold * threshold) begin
                detected <= 1;
            end else begin
                detected <= 0;
            end
        end
    end
endmodule

