module restoring_divider (
    input clk,
    input rst,
    input [3:0] dividend,
    input [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder,
    output reg done
);
    reg [3:0] temp_dividend;
    reg [3:0] temp_quotient;
    reg [2:0] state; // State variable

    parameter IDLE = 3'b000, SHIFT = 3'b001, SUBTRACT = 3'b010, DONE = 3'b011;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            quotient <= 4'b0000;
            remainder <= 4'b0000;
            temp_dividend <= 4'b0000;
            temp_quotient <= 4'b0000;
            state <= IDLE;
            done <= 0;
        end else begin
            case (state)
                IDLE: begin
                    temp_dividend <= dividend;
                    temp_quotient <= 4'b0000;
                    state <= SHIFT;
                    done <= 0;
                end
                SHIFT: begin
                    temp_quotient <= {temp_quotient[2:0], 1'b1};
                    temp_dividend <= {temp_dividend[2:0], 1'b0}; // Shift left
                    state <= SUBTRACT;
                end
                SUBTRACT: begin
                    if (temp_dividend >= divisor) begin
                        temp_dividend <= temp_dividend - divisor;
                    end else begin
                        temp_quotient[0] <= 1'b0; // Set the last bit to 0
                    end
                    if (temp_quotient == 4'b1111) begin
                        state <= DONE;
                    end else begin
                        state <= SHIFT;
                    end
                end
                DONE: begin
                    quotient <= temp_quotient;
                    remainder <= temp_dividend;
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

