module watchdog_timer (  
    input wire clk,  
    input wire rst_n,  
    input wire reset_signal,  
    output reg system_reset  
);  
    parameter TIMEOUT = 8'd100; // Example timeout period  
    reg [7:0] counter;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            counter <= 8'd0;  
            system_reset <= 1'b0;  
        end else if (reset_signal) begin  
            counter <= 8'd0;  
            system_reset <= 1'b0;  
        end else if (counter < TIMEOUT) begin  
            counter <= counter + 1;  
            system_reset <= 1'b0;  
        end else begin  
            system_reset <= 1'b1;  
        end  
    end  
endmodule

