module chacha20_simple (  
    input clk,  
    input reset,  
    input [127:0] key,  
    output reg [31:0] output_data  
);  
    reg [127:0] state;  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= key;  
            output_data <= 32'b0;  
        end else begin  
            // Simple LFSR-like update mechanism  
            state <= {state[126:0], state[127] ^ state[63]};  
            output_data <= state[31:0]; // Output the lower 32 bits  
        end  
    end  
endmodule

