module restoring_divider (
    input clk,
    input reset,
    input start,
    input [3:0] dividend,
    input [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder,
    output reg done
);
    reg [3:0] A; // Accumulator
    reg [3:0] Q; // Quotient register
    reg [3:0] M; // Divisor
    reg [2:0] state; // FSM state

    localparam IDLE = 3'b000,
               LOAD = 3'b001,
               SUBTRACT = 3'b010,
               SHIFT = 3'b011,
               DONE = 3'b100;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            A <= 4'b0;
            Q <= 4'b0;
            remainder <= 4'b0;
            quotient <= 4'b0;
            done <= 0;
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        A <= dividend;
                        M <= divisor;
                        Q <= 4'b0;
                        state <= LOAD;
                    end
                end
                LOAD: begin
                    state <= SUBTRACT;
                end
                SUBTRACT: begin
                    A <= A - M;
                    if (A[3] == 1) begin // If the result is negative
                        A <= A + M; // Restore A
                        Q <= {Q[2:0], 1'b0}; // Shift Q left and append 0
                    end else begin
                        Q <= {Q[2:0], 1'b1}; // Shift Q left and append 1
                    end
                    state <= SHIFT;
                end
                SHIFT: begin
                    if (Q == 4'b1111) // If we've completed 4 bits
                        state <= DONE;
                    else
                        state <= LOAD; // Loop back to LOAD
                end
                DONE: begin
                    quotient <= Q;
                    remainder <= A;
                    done <= 1;
                    state <= IDLE; // Reset to IDLE
                end
            endcase
        end
    end
endmodule

