module pitch_detector(
    input wire clk,
    input wire rst,
    input wire sig, // input square wave signal
    output reg [3:0] freq // output frequency as 4-bit binary
);
    reg [15:0] count; // counter for edges

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            freq <= 0;
