module dma_controller(  
    input clk,  
    input rst,  
    input start,  
    input channel_select,  
    input [7:0] read_data,  
    input [15:0] dest_addr,  
    output reg transfer_done  
);  
    reg [7:0] memory [0:255];  
    reg [7:0] data_buffer;  
    reg active;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            transfer_done <= 0;  
            active <= 0;  
        end else if (start && !active) begin  
            active <= 1;  
            data_buffer <= read_data;  
            // In a real DMA, you'd start the transfer process here  
        end else if (active) begin  
            memory[dest_addr] <= data_buffer;  
            transfer_done <= 1;  
            active <= 0;  
        end else begin  
            transfer_done <= 0;  
        end  
    end  
endmodule

